import { createServer } from "node:http";
import { readFile, writeFile, mkdir } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { randomUUID } from "node:crypto";

const __dirname = dirname(fileURLToPath(import.meta.url));
const DATA_PATH = join(__dirname, "data", "books.json");
const PORT = Number(process.env.PORT) || 3000;

async function loadBooks() {
  try {
    const raw = await readFile(DATA_PATH, "utf8");
    const books = JSON.parse(raw);
    return Array.isArray(books) ? books : [];
  } catch (err) {
    if (err.code === "ENOENT") return [];
    throw err;
  }
}

async function saveBooks(books) {
  await mkdir(dirname(DATA_PATH), { recursive: true });
  await writeFile(DATA_PATH, JSON.stringify(books, null, 2) + "\n");
}

function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function layout(title, body) {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)}</title>
  <style>
    :root { color-scheme: light; }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      font: 16px/1.5 Georgia, "Times New Roman", serif;
      background: #f6f1e7;
      color: #2b241c;
    }
    a { color: #6b3a2a; }
    header, main { max-width: 40rem; margin: 0 auto; padding: 1.25rem; }
    header { padding-bottom: 0; }
    h1 { font-size: 1.75rem; margin: 0 0 0.25rem; }
    h2 { font-size: 1.1rem; margin: 1.75rem 0 0.5rem; letter-spacing: 0.02em; }
    .muted { color: #6e6256; }
    form, .card, article {
      background: #fffdf8;
      border: 1px solid #e4d8c6;
      border-radius: 8px;
      padding: 1rem;
    }
    label { display: block; margin: 0.6rem 0 0.2rem; font-size: 0.9rem; }
    input, textarea {
      width: 100%;
      font: inherit;
      padding: 0.45rem 0.55rem;
      border: 1px solid #cbbba6;
      border-radius: 6px;
      background: #fff;
    }
    textarea { min-height: 6rem; resize: vertical; }
    button, .button {
      display: inline-block;
      margin-top: 0.75rem;
      font: inherit;
      background: #6b3a2a;
      color: #fffdf8;
      border: 0;
      border-radius: 6px;
      padding: 0.4rem 0.8rem;
      text-decoration: none;
      cursor: pointer;
    }
    button.secondary { background: #8a6a4f; }
    ul { list-style: none; padding: 0; margin: 0; }
    li + li { margin-top: 0.6rem; }
    .row { display: flex; justify-content: space-between; gap: 1rem; align-items: baseline; }
    .title { font-weight: 700; text-decoration: none; }
    .empty { margin: 0.25rem 0 0; }
    .actions { display: flex; gap: 0.5rem; align-items: center; }
    .share { font-size: 0.9rem; word-break: break-all; }
  </style>
</head>
<body>
  <header>
    <h1><a href="/" style="color: inherit; text-decoration: none;">Books</a></h1>
    <p class="muted">What you're reading, and what you've finished.</p>
  </header>
  <main>
    ${body}
  </main>
</body>
</html>`;
}

function bookItem(book) {
  const status = book.finished ? "Finished" : "Reading";
  const finish = book.finished
    ? ""
    : `<form method="post" action="/books/${book.id}/finish" style="margin:0;padding:0;border:0;background:transparent;">
         <button class="secondary" type="submit">Mark finished</button>
       </form>`;
  return `<li class="card">
    <div class="row">
      <div>
        <a class="title" href="/books/${book.id}">${escapeHtml(book.title)}</a>
        <div class="muted">${escapeHtml(book.author)} · ${status}</div>
      </div>
      ${finish}
    </div>
  </li>`;
}

function homePage(books) {
  const reading = books.filter((b) => !b.finished);
  const finished = books.filter((b) => b.finished);
  const list = (items) =>
    items.length
      ? `<ul>${items.map(bookItem).join("")}</ul>`
      : `<p class="empty muted">None yet.</p>`;

  return layout(
    "Books",
    `<form method="post" action="/books">
      <h2 style="margin-top:0">Add a book</h2>
      <label for="title">Title</label>
      <input id="title" name="title" required>
      <label for="author">Author</label>
      <input id="author" name="author" required>
      <label for="notes">Notes</label>
      <textarea id="notes" name="notes"></textarea>
      <button type="submit">Add book</button>
    </form>
    <h2>Currently reading</h2>
    ${list(reading)}
    <h2>Finished</h2>
    ${list(finished)}`
  );
}

function bookPage(book, url) {
  const status = book.finished ? "Finished" : "Currently reading";
  const finish = book.finished
    ? ""
    : `<form method="post" action="/books/${book.id}/finish">
         <button type="submit">Mark finished</button>
       </form>`;
  return layout(
    book.title,
    `<article>
      <p class="muted"><a href="/">← All books</a></p>
      <h2 style="margin-top:0">${escapeHtml(book.title)}</h2>
      <p>${escapeHtml(book.author)}</p>
      <p class="muted">${status}</p>
      <h2>Notes</h2>
      <p>${book.notes ? escapeHtml(book.notes).replaceAll("\n", "<br>") : `<span class="muted">No notes yet.</span>`}</p>
      ${finish}
      <p class="share muted">Share this book: <a href="${escapeHtml(url)}">${escapeHtml(url)}</a></p>
    </article>`
  );
}

function notFound() {
  return layout("Not found", `<p>That book isn't here. <a href="/">Back home</a></p>`);
}

function parseForm(body) {
  const params = new URLSearchParams(body);
  return {
    title: (params.get("title") || "").trim(),
    author: (params.get("author") || "").trim(),
    notes: (params.get("notes") || "").trim(),
  };
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    req.on("data", (chunk) => chunks.push(chunk));
    req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
    req.on("error", reject);
  });
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url || "/", `http://${req.headers.host || "localhost"}`);
  const path = url.pathname;

  try {
    if (req.method === "GET" && path === "/") {
      const books = await loadBooks();
      res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
      res.end(homePage(books));
      return;
    }

    const bookMatch = path.match(/^\/books\/([^/]+)$/);
    if (req.method === "GET" && bookMatch) {
      const books = await loadBooks();
      const book = books.find((b) => b.id === bookMatch[1]);
      if (!book) {
        res.writeHead(404, { "Content-Type": "text/html; charset=utf-8" });
        res.end(notFound());
        return;
      }
      const share = `${url.origin}/books/${book.id}`;
      res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
      res.end(bookPage(book, share));
      return;
    }

    if (req.method === "POST" && path === "/books") {
      const form = parseForm(await readBody(req));
      if (!form.title || !form.author) {
        redirect(res, "/");
        return;
      }
      const books = await loadBooks();
      const book = {
        id: randomUUID(),
        title: form.title,
        author: form.author,
        notes: form.notes,
        finished: false,
        createdAt: new Date().toISOString(),
      };
      books.unshift(book);
      await saveBooks(books);
      redirect(res, `/books/${book.id}`);
      return;
    }

    const finishMatch = path.match(/^\/books\/([^/]+)\/finish$/);
    if (req.method === "POST" && finishMatch) {
      const books = await loadBooks();
      const book = books.find((b) => b.id === finishMatch[1]);
      if (!book) {
        res.writeHead(404, { "Content-Type": "text/html; charset=utf-8" });
        res.end(notFound());
        return;
      }
      book.finished = true;
      book.finishedAt = new Date().toISOString();
      await saveBooks(books);
      redirect(res, `/books/${book.id}`);
      return;
    }

    res.writeHead(404, { "Content-Type": "text/html; charset=utf-8" });
    res.end(notFound());
  } catch (err) {
    console.error(err);
    res.writeHead(500, { "Content-Type": "text/plain; charset=utf-8" });
    res.end("Something went wrong.");
  }
});

server.listen(PORT, () => {
  console.log(`Books app listening on http://localhost:${PORT}`);
});

