  const reading = books.filter((b) => !b.finished);
  const finished = books.filter((b) => b.finished);
  const list = (items) =>
    items.length
      ? `<ul>${items.map(bookItem).join("")}</ul>`
      : `<p class="empty muted">None yet.</p>`;

  return layout(
    "Books",
    `<form method="post" action="/books">
      <h2 style="margin-top:0">Add a book</h2>
      <label for="title">Title</label>
      <input id="title" name="title" required>
      <label for="author">Author</label>
      <input id="author" name="author" required>
      <label for="notes">Notes</label>
      <textarea id="notes" name="notes"></textarea>
      <button type="submit">Add book</button>
    </form>
    <h2>Currently reading</h2>
    ${list(reading)}
    <h2>Finished</h2>
    ${list(finished)}`
  );
}

function bookPage(book, url) {
  const status = book.finished ? "Finished" : "Currently reading";
  const finish = book.finished
    ? ""
    : `<form method="post" action="/books/${book.id}/finish">
         <button type="submit">Mark finished</button>
       </form>`;
  return layout(
    book.title,
    `<article>
      <p class="muted"><a href="/">← All books</a></p>
      <h2 style="margin-top:0">${escapeHtml(book.title)}</h2>
      <p>${escapeHtml(book.author)}</p>
      <p class="muted">${status}</p>
      <h2>Notes</h2>
      <p>${book.notes ? escapeHtml(book.notes).replaceAll("\n", "<br>") : `<span class="muted">No notes yet.</span>`}</p>
      ${finish}
      <p class="share muted">Share this book: <a href="${escapeHtml(url)}">${escapeHtml(url)}</a></p>
    </article>`
  );
}

function notFound() {
  return layout("Not found", `<p>That book isn't here. <a href="/">Back home</a></p>`);
}

function parseForm(body) {
  const params = new URLSearchParams(body);
  return {
    title: (params.get("title") || "").trim(),
    author: (params.get("author") || "").trim(),
    notes: (params.get("notes") || "").trim(),
  };
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    req.on("data", (chunk) => chunks.push(chunk));
    req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
    req.on("error", reject);
  });
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url || "/", `http://${req.headers.host || "localhost"}`);
  const path = url.pathname;

  try {
    if (req.method === "GET" && path === "/") {
      const books = await loadBooks();
      res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
      res.end(homePage(books));
      return;
    }

    const bookMatch = path.match(/^\/books\/([^/]+)$/);
    if (req.method === "GET" && bookMatch) {
      const books = await loadBooks();
      const book = books.find((b) => b.id === bookMatch[1]);
      if (!book) {
        res.writeHead(404, { "Content-Type": "text/html; charset=utf-8" });
        res.end(notFound());
        return;
      }
      const share = `${url.origin}/books/${book.id}`;
      res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
      res.end(bookPage(book, share));
      return;
    }

    if (req.method === "POST" && path === "/books") {
      const form = parseForm(await readBody(req));
      if (!form.title || !form.author) {
        redirect(res, "/");
        return;
      }
      const books = await loadBooks();
      const book = {
        id: randomUUID(),
        title: form.title,
        author: form.author,
        notes: form.notes,
        finished: false,
        createdAt: new Date().toISOString(),
      };
      books.unshift(book);
      await saveBooks(books);
      redirect(res, `/books/${book.id}`);
      return;
    }

    const finishMatch = path.match(/^\/books\/([^/]+)\/finish$/);
    if (req.method === "POST" && finishMatch) {
      const books = await loadBooks();
      const book = books.find((b) => b.id === finishMatch[1]);
      if (!book) {
        res.writeHead(404, { "Content-Type": "text/html; charset=utf-8" });
        res.end(notFound());
        return;
      }
      book.finished = true;
      book.finishedAt = new Date().toISOString();
      await saveBooks(books);
      redirect(res, `/books/${book.id}`);
      return;
    }

    res.writeHead(404, { "Content-Type": "text/html; charset=utf-8" });
    res.end(notFound());
  } catch (err) {
    console.error(err);
    res.writeHead(500, { "Content-Type": "text/plain; charset=utf-8" });
    res.end("Something went wrong.");
  }
});

server.listen(PORT, () => {
  console.log(`Books app listening on http://localhost:${PORT}`);
});
